/* The tables of M04 · School setup. */

export const academicYears = defineTable(
  'academic_years',
  { module: 'M04', scope: 'org', member: 'read' },
  {
    ...baseColumns,
    /** `2026–27` */
    name: text().notNull(),
    startDate: dateStr().notNull(),
    /** at most 15 months later */
    endDate: dateStr().notNull(),
    status: enumText(academicYearStatuses).notNull().default('planned'),
    closedAt: timestamptz(),
    closedBy: uuid().references((): AnyPgColumn => profiles.id),
  },
  (t) => [
    check('academic_years_end_date_after', sql`${t.endDate} > ${t.startDate}`),
    check(
      'academic_years_end_date_span',
      sql`${t.endDate} <= (${t.startDate} + interval '15 months')`,
    ),
    uniqueIndex('academic_years_name_uq').on(t.orgId, t.name).where(live(t)),
    uniqueIndex('academic_years_active_uq')
      .on(t.orgId)
      .where(sql`${t.status} = 'active' and ${t.deletedAt} is null`),
  ],
);

export const terms = defineTable(
  'terms',
  { module: 'M04', scope: 'org', member: 'read' },
  {
    ...baseColumns,
    academicYearId: uuid()
      .references((): AnyPgColumn => academicYears.id)
      .notNull(),
    /** `First Term` */
    name: text().notNull(),
    nameUr: text(),
    /** 1, 2, 3 */
    sequence: integer().notNull(),
    /** inside the year */
    startDate: dateStr().notNull(),
    endDate: dateStr().notNull(),
    /** share of the annual result */
    weightPercent: decimal(5, 2).notNull().default(0),
  },
  (t) => [
    positive('terms', t.sequence),
    check('terms_end_date_after', sql`${t.endDate} > ${t.startDate}`),
    between('terms', t.weightPercent, 0, 100),
    uniqueIndex('terms_academic_year_sequence_uq').on(t.academicYearId, t.sequence).where(live(t)),
  ],
);

export const holidays = defineTable(
  'holidays',
  { module: 'M04', scope: 'org', member: 'read' },
  {
    ...baseColumns,
    /** empty means every branch */
    branchId: uuid().references((): AnyPgColumn => branches.id),
    name: text().notNull(),
    nameUr: text(),
    startDate: dateStr().notNull(),
    endDate: dateStr().notNull(),
    kind: enumText(holidayKinds).notNull(),
    /** moon-sighting dates */
    isTentative: boolean().notNull().default(false),
    appliesTo: enumText(holidayAppliesToOptions).notNull().default('everyone'),
  },
  (t) => [
    check('holidays_end_date_from', sql`${t.endDate} >= ${t.startDate}`),
    index('holidays_start_date_end_date_idx').on(t.orgId, t.startDate, t.endDate),
  ],
);

